const __quietstartKits = {
"dailyCheckIn": (// Project-authored business policy. No platform imports, screen reads, input
// execution or daily ledger writes. Targets are opaque refs from one host frame.
function createDailyCheckInKit(options = {}) {
  const dialogs = options.startupDialogs ?? [];
  if (!Array.isArray(dialogs) || dialogs.some(d => !d || typeof d.id !== 'string' ||
      !['tree', 'ocr'].includes(d.source))) throw Error('invalid-daily-policy');
  const copy = value => JSON.parse(JSON.stringify(value));
  function initial(now) {
    return { phase: 'entry', startedAt: now, phaseAt: now, nextReadAt: 0,
      retries: 0, entryRetries: 0, claimed: false, verifiedToday: false, done: false,
      reason: '', startupVisualChecked: false, verificationReopens: 0, actionSequence: 0 };
  }
  const closeRetryMs = 450;
  function isEarlyCloseCheck(s, now) { return s.phase === 'verify' && now < s.phaseAt + closeRetryMs; }
  function cadence(s, now) {
    // Observe on the next event after a confirmed close. A failed early
    // observation resumes at the existing absolute deadline.
    if (s.phase === 'verify' && (s.nextReadAt === s.phaseAt || s.nextReadAt === s.phaseAt + closeRetryMs)) return 0;
    return !s.done && s.phase !== 'entry' && now - s.phaseAt < 4000 ? 150 : 750;
  }
  function successful(s) { return s.done && s.claimed &&
    (s.verifiedToday || s.reason === '签到已领取并返回首页'); }
  function valid(s, now) {
    if (!s || !['entry', 'claim', 'claimSent', 'close', 'verify', 'verifyReward', 'verifyClosedDay'].includes(s.phase) ||
        !Number.isFinite(now) || ['startedAt', 'phaseAt', 'nextReadAt', 'retries', 'entryRetries',
          'verificationReopens', 'actionSequence'].some(k => !Number.isSafeInteger(s[k]) || s[k] < 0) ||
        ['claimed', 'verifiedToday', 'done', 'startupVisualChecked'].some(k => typeof s[k] !== 'boolean')) {
      throw Error('invalid-daily-checkpoint');
    }
  }
  function result(s, outcome = 'waiting', intent, applied) {
    return { status: s.done ? 'complete' : 'running', outcome, checkpoint: s,
      ...(intent ? { intent } : {}), ...(applied ? { applied } : {}) };
  }
  function tap(s, ref, purpose, outcome, applied, optional = false) {
    if (typeof ref !== 'string' || !ref) throw Error('invalid-daily-target');
    return result(s, outcome, { kind: 'tap', targetRef: ref, purpose, optional,
      sequence: s.actionSequence }, applied);
  }
  function dismissal(s) { return { stamp: s.phase === 'entry', delay: 650, startupVisualChecked: false }; }
  function dismiss(s, target, purpose) { return tap(s, target, purpose, 'dismissed', dismissal(s)); }
  function commitDismissal(s, receipt) {
    return commit({ checkpoint: s, outcome: 'dismissed', applied: dismissal(s),
      intent: { kind: 'tap', sequence: s.actionSequence } }, receipt);
  }
  function homeReady(f) { return f.home && f.canEnter && !f.modal && !f.dialog && !f.claimVisible; }
  function finishOnHome(s) {
    s.done = true; s.reason = '签到已领取并返回首页';
    return result(s, 'success');
  }
  function closeResult(s, f) {
    return tap(s, f.closeTarget, 'close', 'closed', { stamp: true, phase: 'verify', delay: 0 });
  }
  function confirmClaim(s, f, now) {
    s.claimed = true;
    s.phase = 'close';
    s.phaseAt = now;
    s.nextReadAt = 0;
    return f.dialog && !f.claimVisible && f.closeTarget ? closeResult(s, f) : result(s, 'claimed');
  }
  function reopen(s, f) {
    if (!homeReady(f) || !f.entryTarget) return result(s);
    return tap(s, f.entryTarget, 'reopen-to-verify', 'entry',
      { stamp: true, phase: 'verifyReward', delay: 150, verificationReopensDelta: 1 });
  }
  function decide(checkpoint, observation) {
    const { now, facts: f } = observation ?? {};
    valid(checkpoint, now);
    const s = copy(checkpoint);
    if (s.done) return result(s, 'done');
    if (now < s.nextReadAt) return result(s);
    s.nextReadAt = now + (cadence(s, now) === 150 ? 150 : 650);
    if (isEarlyCloseCheck(s, now)) {
      // This one early read can only finish from current native proof.
      // Loading, another dialog or a lost owner keeps the original deadline.
      if (f?.ownerValid === true && f.completionProven && homeReady(f) &&
          !dialogs.some(rule => f.startup?.[rule.id]?.matched)) return finishOnHome(s);
      s.nextReadAt = s.phaseAt + closeRetryMs;
      return result(s);
    }
    // A failed capture or a foreign/ambiguous owner cannot produce a target.
    if (!f || f.ownerValid !== true) return result(s);
    for (const key of ['home', 'dialog', 'completed', 'claimed', 'claimVisible', 'modal', 'canEnter']) {
      if (typeof f[key] !== 'boolean') throw Error('invalid-daily-facts:' + key);
    }
    const sameDayClose = s.phase === 'verifyClosedDay' && homeReady(f) && f.completionProven &&
      new Date(now).toDateString() === new Date(s.phaseAt).toDateString();
    if (f.completed && f.dialog || sameDayClose) {
      s.claimed = true; s.verifiedToday = true; s.done = true; s.reason = '已确认今天签到';
      return s.phase !== 'verifyClosedDay' && f.confirmedDayCloseTarget ?
        tap(s, f.confirmedDayCloseTarget, 'close-confirmed', 'success',
          { reason: '已确认今天签到并关闭弹窗' }, true) : result(s, 'success');
    }
    const entering = s.phase === 'entry';
    const signInVisible = f.dialog || f.claimVisible || f.claimed || f.completed;
    if (entering && f.dialog && f.claimTarget) return tap(s, f.claimTarget, 'claim', 'claim',
      { stamp: true, phase: 'claimSent', delay: 150 });
    for (const rule of dialogs) {
      const proof = f.startup?.[rule.id];
      if (rule.source !== 'tree' || !proof?.matched || !entering && rule.entryOnly) continue;
      if (proof.targetRef) return dismiss(s, proof.targetRef, rule.id);
      if (entering || !signInVisible) return result(s);
    }
    if (entering || !signInVisible) {
      if (f.modal && f.modalDismissTarget) return dismiss(s, f.modalDismissTarget, 'explicit-modal-dismiss');
      if (!s.startupVisualChecked && f.modal && f.home) {
        s.startupVisualChecked = true;
        for (const rule of dialogs) {
          if (rule.source !== 'ocr') continue;
          const proof = f.ocr?.[rule.id];
          if (!proof) {
            // The adapter gathers this declared crop, then calls decide again
            // with the original checkpoint and this same frame's facts.
            return result(copy(checkpoint), 'waiting', { kind: 'read-ocr', ruleRef: rule.id,
              readRegion: rule.readRegion, format: 'jpeg', maxMs: 900 });
          }
          if (proof.failed) { s.startupVisualChecked = false; return result(s); }
          if (!proof.matched) continue;
          return proof.targetRef ? dismiss(s, proof.targetRef, rule.id) : result(s);
        }
      }
      if (f.modal) return result(s);
      s.startupVisualChecked = false;
    }
    if (s.phase === 'verifyClosedDay') {
      if (!f.dialog || !f.claimVisible) return reopen(s, f);
      s.phase = 'claim';
    }
    if (entering && !f.canEnter) return result(s);
    if (s.phase === 'verifyReward') {
      if (f.dialog && f.claimed && !f.claimVisible) return confirmClaim(s, f, now);
      if (now - s.phaseAt > 2500 && f.claimVisible && f.dialog) {
        s.phase = 'claim'; s.phaseAt = now; s.nextReadAt = now;
        s.reason = '复查仍有未领取任务，接续领取';
        if (f.claimTarget) return tap(s, f.claimTarget, 'claim', 'claim', { stamp: true, phase: 'claimSent', delay: 150 });
        return result(s);
      }
      // A dispatch receipt proves the click, not that the panel opened.
      // Use the original entry retry cadence on a newly proven home.
      return now - s.phaseAt >= 1600 ? reopen(s, f) : result(s);
    }
    if (s.phase === 'verify') {
      if (homeReady(f)) return f.completionProven ? finishOnHome(s) : reopen(s, f);
      return f.dialog && f.claimed && !f.claimVisible && f.closeTarget && now - s.phaseAt >= 1600 ?
        closeResult(s, f) : result(s);
    }
    if (s.phase === 'close') return f.closeTarget ? closeResult(s, f) : reopen(s, f);
    if (s.phase === 'claimSent') {
      if (f.completed || f.claimed) return confirmClaim(s, f, now);
      if (now - s.phaseAt > 1200 && homeReady(f)) return reopen(s, f);
      if (now - s.phaseAt > 6500 && f.claimTarget) {
        s.retries++;
        return tap(s, f.claimTarget, 'claim', 'claim', { stamp: true, phase: 'claimSent', delay: 150 });
      }
      return result(s);
    }
    if (s.phase === 'claim' && f.claimTarget) return tap(s, f.claimTarget, 'claim', 'claim',
      { stamp: true, phase: 'claimSent', delay: 150 });
    if (s.phase === 'claim') {
      if (now - s.phaseAt >= 1600 && homeReady(f)) {
        if (f.entryTarget) return tap(s, f.entryTarget, 'retry-entry', 'entry',
          { stamp: true, delay: 150, entryRetriesDelta: 1 });
      }
      return result(s);
    }
    return f.entryTarget ? tap(s, f.entryTarget, 'entry', 'entry',
      { stamp: true, phase: 'claim', delay: 150 }) : result(s);
  }
  function commit(decision, receipt) {
    if (!decision.intent || decision.intent.kind !== 'tap' || !receipt ||
        !['applied', 'rejected', 'unknown'].includes(receipt.status) ||
        receipt.sequence !== decision.intent.sequence || !Number.isSafeInteger(receipt.at) || receipt.at < 0) {
      throw Error('invalid-daily-receipt');
    }
    const s = copy(decision.checkpoint);
    if (receipt.status !== 'applied') {
      // Closing is optional after definitive completed evidence. An uncertain
      // ordinary input is owned by the host action ledger and must not repeat.
      return decision.intent.optional ? result(s, decision.outcome) :
        { status: 'paused', outcome: 'waiting', reason: 'input-' + receipt.status, checkpoint: s };
    }
    const next = decision.applied;
    if (next.stamp) s.phaseAt = receipt.at;
    if (next.delay !== undefined) s.nextReadAt = receipt.at + next.delay;
    if (next.phase) s.phase = next.phase;
    if (next.reason) s.reason = next.reason;
    if (next.startupVisualChecked !== undefined) s.startupVisualChecked = next.startupVisualChecked;
    s.entryRetries += next.entryRetriesDelta ?? 0;
    s.verificationReopens += next.verificationReopensDelta ?? 0;
    s.actionSequence++;
    return result(s, decision.outcome);
  }
  return { initial, decide, commit, cadence, successful, isEarlyCloseCheck, commitDismissal };
})
};
const __quietstartDailyDialogs=[{"id":"startup-0","source":"tree","entryOnly":true},{"id":"startup-1","source":"tree"},{"id":"startup-2","source":"ocr","readRegion":[0.08,0.14,0.9,0.59]}];
const __quietstartDailyDismissQueries=["modal-dismiss-0","modal-dismiss-1","modal-dismiss-2","modal-dismiss-3","modal-dismiss-4"];
// The locked, unchanged Kit owns business state. The host owns every query,
// target reference, input receipt and day-completion proof.
const dailyPolicy = __quietstartKits.dailyCheckIn({ startupDialogs: __quietstartDailyDialogs });
const matched = (queries, id) => queries[id]?.matched === true;
const target = (queries, id) => matched(queries, id) ? queries[id]?.targetRef : undefined;

function factsFrom(frame) {
  if (frame?.ownerValid !== true) return { ownerValid: false };
  const q = frame.queries || {};
  const facts = { ownerValid: true, home: matched(q, 'home'), dialog: matched(q, 'dialog'),
    completed: matched(q, 'completed'), claimed: matched(q, 'claimed'),
    claimVisible: matched(q, 'claimVisible'), modal: matched(q, 'modal'),
    canEnter: matched(q, 'canEnter'), entryTarget: target(q, 'entry'),
    claimTarget: target(q, 'claim'), closeTarget: target(q, 'close'),
    confirmedDayCloseTarget: target(q, 'closeConfirmedDay'), completionProven: !!frame.completionProof, startup: {}, ocr: {} };
  for (const id of __quietstartDailyDismissQueries) {
    const ref = target(q, id);
    if (ref) { facts.modalDismissTarget = ref; break; }
  }
  for (const rule of __quietstartDailyDialogs) {
    if (rule.source === 'tree') facts.startup[rule.id] = {
      matched: matched(q, rule.id + '-context'), targetRef: target(q, rule.id)
    };
  }
  return facts;
}

function message(decision) {
  if (decision.checkpoint.reason) return decision.checkpoint.reason;
  return { entry: '签到入口已打开', claim: '已点击领取，等待确认', claimed: '已确认领取，等待关闭',
    closed: '已关闭签到结果，核对首页', dismissed: '已关闭遮挡，接续签到',
    success: '今日签到已确认' }[decision.outcome] || '正在检查签到页面';
}

function output(checkpoint, now, outcome, completionProof) {
  const successful = dailyPolicy.successful(checkpoint);
  const done = checkpoint.done === true;
  const decision = { checkpoint, outcome };
  if (successful && !completionProof) throw Error('daily-completion-proof-missing');
  return { status: done ? 'complete' : 'waiting', checkpoint: { policy: checkpoint },
    ...(done ? {} : { next: { at: Math.max(now + dailyPolicy.cadence(checkpoint, now),
      checkpoint.nextReadAt, now) } }),
    ...(successful ? { successProof: completionProof } : {}),
    message: message(decision), outcome, successful };
}

async function __quietstartConfiguredOriginalEvent(ctx, event) {
  if (event?.kind !== 'tick' || !Number.isSafeInteger(event.actionSequence) || event.actionSequence < 0) {
    throw Error('invalid-daily-event');
  }
  const now = await ctx.clock.now();
  let before = ctx.checkpoint?.policy;
  if (before == null) {
    before = dailyPolicy.initial(now);
    before.actionSequence = event.actionSequence;
  }
  const key = ctx.run.recoveryActionKey;
  if (!before.done && key === ctx.run.id + '/' + before.actionSequence) {
    const query = ctx.run.recoveryDirectQueryRef;
    const dismissal = __quietstartDailyDismissQueries.includes(query) || __quietstartDailyDialogs.some(rule =>
      rule.id === query && (!rule.entryOnly || before.phase === 'entry'));
    if (dismissal) {
      const receipt = await ctx.actions.lookup({ idempotencyKey: key });
      if (!receipt.found || receipt.status !== 'applied' || receipt.sequence !== before.actionSequence) {
        throw Error('daily-dismissal-receipt-mismatch');
      }
      const resumed = dailyPolicy.commitDismissal(before, receipt);
      const result = output(resumed.checkpoint, now, resumed.outcome);
      await ctx.ui.publish({ kind: 'capsule', message: result.message, stopped: false });
      return result;
    }
    // The host will only replay this exact declared action during recovery.
    // Its receipt can advance the sequence, while success needs a fresh proof.
    const receipt = await ctx.actions.perform({ kind: 'tap-query', ruleRef: 'closeConfirmedDay', idempotencyKey: key });
    if (receipt.status === 'already-applied' && receipt.sequence === before.actionSequence) {
      const resumed = { ...before, actionSequence: receipt.sequence + 1, phase: 'verifyClosedDay',
        phaseAt: receipt.at, nextReadAt: now, reason: '已接续关闭结果，核对今日签到' };
      return output(resumed, now, 'waiting');
    }
  }
  if (!before.done && now < before.nextReadAt) return output(before, now, 'waiting');
  if (!before.done) {
    const due = dailyPolicy.decide(before, { now, facts: { ownerValid: false } });
    if (due.checkpoint.done) return output(due.checkpoint, now, due.outcome);
  }
  let selection;
  if (!before.done) {
    const startupVisual = !before.startupVisualChecked && !dailyPolicy.isEarlyCloseCheck(before, now);
    selection = await ctx.actions.select({ queryRefs: ["home","dialog","completed","claimed","claimVisible","modal","canEnter","entry","claim","close","closeConfirmedDay","modal-dismiss-0","modal-dismiss-1","modal-dismiss-2","modal-dismiss-3","modal-dismiss-4","startup-0-context","startup-0","startup-1-context","startup-1"],
      ...(startupVisual ? { visualRefs: ['startup-2'],
        visualUnless: ['startup-0-context', 'startup-1-context',
          ...(before.phase === 'entry' ? [] : ['claimVisible', 'completed', 'claimed']),
          ...(before.phase === 'verifyClosedDay' ? ['canEnter'] : []), ...__quietstartDailyDismissQueries] } : {}),
      input: { before, now, startupVisual }, idempotencyKey: ctx.run.id + '/' + before.actionSequence });
  }
  const value = selection?.value;
  const frame = value || await ctx.observe.snapshot({ fields: ['queries'], reason: '核对签到声明和当前目标' });
  const facts = value ? value.ocrFacts : factsFrom(frame);
  let decision = value ? value.decision : dailyPolicy.decide(before, { now, facts });
  let ocrReads = 0;
  while (decision.intent?.kind === 'read-ocr') {
    if (++ocrReads > __quietstartDailyDialogs.length || !__quietstartDailyDialogs.some(rule =>
      rule.id === decision.intent.ruleRef && rule.source === 'ocr')) throw Error('undeclared-daily-ocr');
    facts.ocr[decision.intent.ruleRef] = await ctx.vision.ocr({ ruleRef: decision.intent.ruleRef });
    // The Kit deliberately reevaluates the original checkpoint and the same
    // captured facts after the declared OCR proof has been gathered.
    decision = dailyPolicy.decide(before, { now, facts });
  }
  if (decision.intent?.kind === 'tap') {
    const intent = decision.intent;
    let receipt;
    try {
      receipt = value?.selected ? selection.receipt : await ctx.actions.perform({ kind: 'tap', targetRef: intent.targetRef,
        idempotencyKey: ctx.run.id + '/' + intent.sequence });
    } catch (error) {
      if (!intent.optional || !frame.completionProof) throw error;
      receipt = { status: 'unknown', at: await ctx.clock.now(), sequence: intent.sequence };
    }
    if (receipt.status === 'not-dispatched') {
      if (intent.optional && frame.completionProof) {
        decision = dailyPolicy.commit(decision, { status: 'rejected',
          sequence: intent.sequence, at: receipt.at });
      } else {
        // No input or durable intent exists. Retry the original Kit state;
        // keep its phase/total deadline and action sequence unchanged.
        const retryAt = await ctx.clock.now();
        const provenClaim = intent.purpose === 'close' && decision.checkpoint.phase === 'close' && decision.checkpoint.claimed;
        const retry = JSON.parse(JSON.stringify(provenClaim ? decision.checkpoint : before));
        retry.nextReadAt = Math.max(retry.nextReadAt, retryAt + 150);
        return output(retry, retryAt, 'waiting');
      }
    } else {
      decision = dailyPolicy.commit(decision, { ...receipt,
        status: receipt.status === 'already-applied' ? 'applied' : receipt.status });
    }
  }
  if (decision.status === 'paused') throw Error(decision.reason || 'daily-input-unconfirmed');
  const result = output(decision.checkpoint, await ctx.clock.now(), decision.outcome, frame.completionProof);
  if (decision.outcome !== 'waiting') await ctx.ui.publish({ kind: 'capsule', message: result.message,
    stopped: result.status === 'complete' });
  return result;
}

const __quietstartConfiguredControls={"tasks":[],"stages":[],"safeFinish":true};
// Author-side settings adapter. This never changes target declarations, input
// permissions, original checkpoints, or an application's completion conditions.
export async function onEvent(ctx, event) {
  if (event?.kind === 'input-select') {
    const { before, now, startupVisual } = event.input;
    const facts = factsFrom(event.observation);
    const promo = event.observation.queries?.['startup-2'];
    if (startupVisual && promo && facts.ownerValid) facts.ocr['startup-2'] = promo;
    const decision = dailyPolicy.decide(before, { now, facts });
    const intent = decision.intent;
    const selected = intent?.kind === 'tap' && !intent.optional;
    return { action: selected ? { kind: 'tap', targetRef: intent.targetRef } : null,
      value: { decision, selected, completionProof: event.observation.completionProof,
        ...(intent?.kind === 'read-ocr' ? { ocrFacts: facts } : {}) } };
  }
  const config = await ctx.config.read();
  const controls = typeof __quietstartConfiguredControls === 'object' ? __quietstartConfiguredControls : {};
  if (controls.tasks?.length) {
    const disabled = new Set(controls.tasks.filter(task => config[task.key] === false).map(task => task.id));
    // Local settings only subtract from the host's current authorized list.
    // Missing native lists retain the original adapter's fail-closed behavior.
    if (Array.isArray(event?.enabledTaskIds)) {
      const selected = event.enabledTaskIds.filter(id => !disabled.has(id));
      if (controls.supportTasks?.length && controls.tasks.filter(task => !controls.supportTasks.includes(task.id)).every(task => disabled.has(task.id))) selected.splice(0);
      event = controls.safeFinish ? { ...event, selectedTaskIds: selected } : { ...event, enabledTaskIds: selected };
    }
    else if (disabled.size === controls.tasks.length) event = { ...event, enabledTaskIds: [] };
  }
  const prefix = typeof config.progressPrefix === 'string' ? config.progressPrefix.trim() : '';
  const message = text => prefix && typeof text === 'string' && text ? (prefix + ' · ' + text).slice(0, 500) : text;
  const port = { ...ctx, config: { ...ctx.config, read: async () => config },
    ...(prefix && ctx.ui?.publish ? { ui: { ...ctx.ui,
      publish: item => ctx.ui.publish({ ...item, message: message(item.message) }) } } : {}) };
  const result = await __quietstartConfiguredOriginalEvent(port, event);
  if (prefix && typeof result?.message === 'string') result.message = message(result.message);
  const delay = config.nextActionDelayMs;
  if (result?.status === 'waiting' && result.next && Number.isSafeInteger(delay) && delay > 0) {
    result.next = { ...result.next, at: Math.max(result.next.at, (await ctx.clock.now()) + delay) };
  }
  return result;
}

export function migrate(input) {
  if (input?.from !== 'legacy-daily-checkin/1') throw Error('unsupported-daily-migration');
  const checkpoint = input.checkpoint ?? { policy: null };
  if (!checkpoint || typeof checkpoint !== 'object' || Array.isArray(checkpoint) ||
    Object.keys(checkpoint).some(key => key !== 'policy') ||
    checkpoint.policy !== null && (typeof checkpoint.policy !== 'object' || Array.isArray(checkpoint.policy))) {
    throw Error('invalid-daily-adapter-checkpoint');
  }
  return { schema: 1, checkpoint };
}
